INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (35,1,'4) Diarepan/Didepan Pinandita : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan disertai dengan Upakara (Banten) Pembersihan (Durmanggala, Prayascita, Penglukatan menggunakan sibeh pepek, payuk, eteh-eteh pembersihan dan lis penglukatan)','123');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (36,1,'5) Sor : Caru ayam brumbun dengan kelengkapan Upakara(Banten) Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Suci Sari/Alit, Tumpeng pitu alit, Biyakala, Segehan, Kewangen, Penjor caru, Bayang-bayang ayam brumbun, Olahan caru (kawisan, karangan, ketengan, bayuhan, bakaran), Nasi wong-wongan, perlengkapan lain se perti : Sampat, tulud, Tetimpug, Kulkul, Sengkwi.','123-124');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (37,1,'1) Padmasana sebagai Surya Pras, Daksina. Sodan/Rayunan/Ajuman, Tipat kelanan.','124');
