INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (44,1,'2) Sanghyang Pertiwi : Pras, Daksina, Sodan/ Rayunan/Ajuman, Tipat Kelanan, Suci Sari/ Alit.','125');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (45,1,'3) Arepan Sanggah Surya : Pras, Pengambean, Pungulapan, Dapetan atau Tumpeng Pitu dan Bayuan Alit.','125');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (46,1,'4) Diarepan/Didepan Pinandita : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Suci Sari/Alit disertai dengan Upakara (Banten) Pembersihan (Durmanggala, Prayascita, Penglukatan menggunakan sibeh pepek, payuk, eteh-eteh pembersihan dan lis penglukatan)','125');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (47,1,'5) Sor : Caru ayam brumbun dengan kelengkapan Upakara (Banten) Pras, Daksina, Sodan/Rayunan/Ajuman. Tipat kelanan, Suci Sari/Alit, Tumpeng pitu, Biyakala, Segehan agung, Kewangen, Penjor caru, Bayang-bayang ayam brumbun, Olahan caru (kawisan, karangan, ketengan, bayuhan, bakaran), Nasi wong-wongan, perlengkapan lain Sampat, tulud, Tetimpug, Kulkul, Sengkwi.','125');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (48,1,'1) Upakara (Banten) Pemendak Ida Bhatara di Bale Papelik : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Suci Sari/ Alit, Prayascita, Byakala, Segehan agung, Banten Pemendak, Pengiring dan Penuntun Dewa.','126');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (49,1,'2) Upakara(Banten) di Beji : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Suci Sari/Alit, sayut Mertha sari, Banten Pembersihan lengkap dengan eteh-eteh pesucian.','126');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (50,1,'3) Upakara (Banten) di Sanghyang Surya : Pras, Daksina, Sodan/Rayunan/Ajuman , Tipat kelanan, Suci Sari/Alit di tambah dengan banten pemogpog, dilengkapi dengan rantasan dan Gelar Sanga.','126');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (51,1,'4) Upakara (Banten) di Padmasana dan Pelinggih Pengiring sakral setara :Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Suci Sari/Alit, lengkap dengan rantasannya, Daksina Pralingga, dan Tirtha sesuaikan dengan Pelinggih masing-masing.','126');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (52,1,'5) Upakara (Banten) di Lapan/Ajeng Padmasana : Pras, Daksina, Sodan/Rayunan/Aju man, Tipat kelanan, Suci Sari/Alit, Tumpeng 11 (Pengulap, Pangambean, Dapetan, Penyeneng, Guru, Pengiring, Pengapit, Jerimpen (2), Gebogan (2), dilengkapi dengan Banten Guru Piduka, Sayut Mertha Dewa, Sida Karya, Sida Purna, Pasupati.','126-127');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (53,1,'6) Upakara (Banten) di Pelinggih sakral tidak setara (Penglurah, Bale Kulkul, Apit lawang (2), Bale perantenan, Bale piyasan, Bale Gong, Bale Penyimpenan : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan.','127');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (54,1,'7) Diarepan/Didepan Pinandita : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Suci Sari/Alit, Rantasan.','127');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (55,1,'8) Upakara (Banten) Penyineban : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, dan Suci Sari/Alit.','127');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (56,1,'1) Sanggah Surya : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Suci Laksana, dibawah Sanggah Surya Gelar Sanga.','127');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (57,1,'2) Sanghyang Pertiwi : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Suci Laksana.','127');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (58,1,'3) Arepan Sanggah Surya : Pra, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Suci Laksana, Pengambean, Pungulapan, Dapetan atau Tumpeng Pitu dan Bayuan Alit.','128');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (59,1,'4) Diarepan/Didepan Pinandita : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Suci Laksana disertai dengan Upakara (Banten) Pembersihan (Durmanggala, Prayascita, Penglukatan menggunakan sibeh pepek, payuk, eteh-eteh pembersihan dan lis penglukatan)','128');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (60,1,'5) Sor : Caru Panca sata dengan kelengkapan Upakara (Banten) Pras, Daksina, Sodan/ Rayunan/Ajuman. Tipat kelanan, Suci Laksana ditengah Caru ayam brumbun sedangkan dimasing-masing Caru (ayam putih, merah, kuning, hitam) cukup dengan Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Tumpeng pitu, Bayuan alit, Biyakala, Segehan agung, Kewangen, Penjor caru, Bayang-bayang ayam sesuai warna), Olahan caru untuk masing-masing ayam (kawisan, karangan, ketengan, bayuhan, bakaran), Nasi wong-wongan (sesuaikan dengan warna masing-masing ayam), perlengkapan lain Sampat, tulud, Tetimpug, Kulkul, Sengkwi.','128');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (61,1,'6) Upakara (Banten) Pemendak Ida Bhatara di Bale Papelik : Pras, Daksina, Sodan/Rayunan/ Ajuman, Tipat kelanan, Suci Laksana, Prayascita, Byakala, Segehan agung, Banten Pemendak, Pengiring dan Penuntun Dewa.','129');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (62,1,'7) Upakara(Banten) di Beji : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Suci Laksana, sayut Mertha sari, Banten Pemersihan lengkap dengan eteh-eteh pesucian.','129');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (63,1,'8) Upakara (Banten) di Sanghyang Surya : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Suci Laksana (2 Soroh), (1 Soroh ke Sanghyang Surya dan 1 Soroh lagi ke Sanghyang Giripati) di tambah dengan banten pemogpog, dilengkapi dengan rantasan.','129');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (64,1,'9) Upakara (Banten) di Padmasana dan Pelinggih Pengiring sakral setara : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Suci Laksana, lengkap dengan rantasannya, Daksina Pralingga, dan Tirtha sesuaikan dengan Pelinggih masing-masing.','129');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (65,1,'10) Upakara (Banten) di Lapan/Ajeng Padmasana : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Suci Laksana, Tumpeng 21 (Pengulap, Pangambean, Dapetan, Penyeneng, Guru, Pengiring, Pengapit, Udel, Kurenan, Ancak, Bingin, Pancoran, Tagog, Pulagembal, Sekar setaman, Jerimpen (2), Gebogan (2), dilengkapi dengan Banten Guru Piduka, Sayut Mertha Dewa, Sida Karya, Sida Purna, Sayut Pasupati. (karena dalam tingkatan Upacara ini Senjata Nawa Sanga dipasang/medal)','129-130');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (66,1,'11) Upakara (Banten) di Pelinggih sakral tidak setara (Penglurah, Bale Kulkul, Apit lawang (2), Bale perantenan, Bale piyasan : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Suci Sari/Alit.','130');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (67,1,'12) Diarepan/Didepan Pandita dan atau Pandita: Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Suci Laksana, ditambah dengan Sayut Dharma Wiku.','130');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (68,1,'13) Upakara (Banten) Penyineban: Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, dan Suci Laksana.','130');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (69,1,'1) Padmasana sebagai Surya Pras, Daksina. Sodan/Rayunan/Ajuman, Tipat kelanan.','130');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (70,1,'2) Dilapan sebagai persembahan Pras, Pengambena, Dapetan dan Prayascita.','131');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (71,1,'3) Banten Sor : Segehan.','131');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (72,1,'4) Pelinggih Pengiring Pokok setara cukup Sodan/Rayunan/Ajuman.','131');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (73,1,'5) Penglurah : Tipat kelanan.','131');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (74,1,'6) Diarepan/Didepan Pinandita : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan.','131');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (75,1,'1) Padmasana sebagai Surya Pras, Daksina. Sodan/Rayunan/Ajuman, Tipat kelanan.','131');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (76,1,'2) Dilapan sebagai persembahan Pras, Pengambena, Dapetan, Beras, Bumbu dapur, Minyak goreng, dan lain-lain.','131');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (77,1,'1) Upakara (Banten) Nyikut karang : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, minimal Canang Sari (5) buah dan Segehan Agung. Bila menggunakan Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan ditempatkan ditengah sedangkan di pojok-pojok menggunakan canang sari, bila hanya menggunakan canang sari (5) buah, maka penempatannya ditengah dan dipojok-pojok serta segehan ditempatkan ditengah-tengah karang yang akan di ukur/ di sikut.','132');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (78,1,'2) Upakara (Banten) Ngeruak karang : Upakara (Banten) ke Surya Pras, Daksina,Sodan/Rayunan/Ajuman, Tipat kelanan, dilengkapi dengan Caru Ngeruak karang (ayam brumbun) lihat tata upakara (banten) caru eka sata dengan tetandingan olahan carunya hanya diambil tetandingan ketengannya saja sesuaikan dengan urip 33 (Timur 5, Selatan 9, Barat 7, Utara 4 dan ditengah 8) ditambahkan satu tandingan pemopog terdiri dari urab barak, putih, gegecok dan untuk masing-masing satenya 3 tusuk (sate lembat, sate calon, sate asem).','132-133');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (79,1,'3) Upakara (Banten) Nasarin atau Mendem Dasar : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan ditambah dengan Pras Pemendeman (Tumpeng merah), dengan kelengkapannya 2 buah Bata merah. 1 Bata Merah di bungkus dengan kain putih bergambarkan Padma bertuliskan Dasa Aksara dan diikat dengan benang tridatu. 1 Batah Merah lagi dibungkus dengan kain putih bergambarkan bedawangnala dengan aksara Mang dan diikat dengan benang Tridatu masing-masing dilengkapi kwangen, Bungkak kelapa gading yang dibungkus kain putih bertuliskan aksara Ongkara, kemudian dimasukkan sebuah kwangen kedalam bungkak kelapa gading dengan uang kepeng 11.','133');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (80,1,'4) Upakara (Banten) Pemelaspas : di dahului dengan Upacara Caru Pemelaspas dapat menggunakan Caru Eka sata atau Caru Panca sata, menggunakan Sanggah Surya (lihat upakara (banten) Caru Eka sata dan Pancasata).','133-134');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (81,1,'5) Upakara (Banten) Pemakuhan dan Pengurip- urip : Bila yang diplaspas adalah bangunan suci, alangkah baiknya dilengkapi dengan Caru pemakuhan dengan menggunakan ayam putih, mengenai tetandingannya sesuai dengan urip ayam putih (5) dengan tidak menggunakan Sanggah Caru. Kelengkapan Upakara (Banten) Pemakuhan: Pras, Daaksina, Sodan/Rayunan/Ajuman, Tipat kelanan, dan sarana pengurip-urip: kapur, arang, kunyit, bubuk cendana, dengan sarana pemakuh palu dan pahat.','134');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (82,1,'6) Upakara (Banten) Tataban : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Pengulapan, Pengambean, Dapetan, Penyeneng, Bayuan Alit.','134');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (83,1,'7) Upakara (Banten) Sor : Segehan cacahan.','134');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (84,1,'1) Mohon Tirtha di Sanggah Surya dan Sanggah Kemulan : Pras, Ajuman, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan dan segehan.','145');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (85,1,'2) Upakara (Banten) arepan Pemangku : Pras, Ajuman, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Tirtha Pembersihan dan Tirtha Penglukatan.','145');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (86,1,'3) Saji Tarpana untuk Sawa : Pras, Ajuman, Daksina, Canang sari, Bubur Pirata, Punjungan putih kuning, Nasi angkeb, rantasan, cecepan/carat, Beras catur.','145');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (87,1,'4) Upakara (Banten) teben : Segehan Manca warna.','145');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (88,1,'5) Kelengkapan lain : Kwangen, Sekar ura.','145');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (89,1,'1) Pras, Ajuman, Daksina, Sodan/Rayunan/ Ajuman, Tipat kelanan, dan Segehan (Surya, Prajapati, Sedehan setra dan untuk Memperabukan ke Sanghyang Agni)','145-146');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (90,1,'2) Banten arepan Pemangku : Pras, Ajuman, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan. Tirtha Pembersihan,, Tirtha Penglukatan, Tirtha Prajapati dan Tirtha Pekuluh dari Pura yang diemong, Tirtha Kawitan serta Prayascita.','146');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (91,1,'3) Daksina Pemendem 1 buah (bila jenasah di makamkan atau dikubur)','146');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (92,1,'4) Banten Bangbang (liang lahat): Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan. (bila jenasah di makamkan atau dikubur)','146');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (93,1,'1) Upakara (Banten) untuk Ngreka : Pras, Ajuman, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan dan Segehan.','146');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (94,1,'3) Kwangen untuk pengereka tulang 7 buah.','146');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (95,1,'4) Banten Teben : Segehan Manca warna.','146');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (96,1,'5) Upakara (Banten) untuk Ngayut : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, dan Tirtha Pura Segara.','146');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (97,1,'6) Upakara (Banten) Prayascita untuk penyucian diri umat yang hadir.','147');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (98,1,'1) Upakara (Banten) ke Surya, ke Dalem atau Prajapati, Sedahan Setra. : Pras, Daksina, Sodan/Ajuman, Tipat kelanan.','147');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (99,1,'2) Upakara (Banten) Nunas Tirtha Pengerapuhan, Ajuman Putih Kuning, Bubur Sumsum 5 takir, Tompeng Poleng meplekir berisi kewangen 1 buah, Padang Lepas 5 batang, muncuk ambengan 5 muncuk, Payuk Anyar 1 buah medaging toya dan seet mingmang 1 buah.','147');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (100,1,'3) Upakara (Banten) ke Bambang Rare : Pras, Daksina, Sodan/Ajuman, Tipat kelanan, Canang Sari, Pengulapan, Kelungah Nyuh Gading mesurat ONG KARA berisi Rwaning Waringin 3 muncuk/pucuk dengan seet mimang 6 katih/buah dijadikan satu menggunakan tali benang cemeng tiga putaran atau ileh.','147');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (101,1,'4) Upakara (Banten) untuk Sawa (Pitra Rare): Pras, Daksina, Sodan/Ajuman, Tipat kelanan, Canang Sari, Punjung Putih Kuning, Banten Bajang, Bangsah Pinang, Kereb Sari dan Bunga Pudak.','147');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (102,1,'5) Upakara (Banten) untuk arepan Pinandita/ Pemangku : Pras, Daksina, Sodan/Ajuman, Tipat Kelanan, Canang sari, Tirtha Penglukatan, Tirtha Pabersihan, Tirtha Prajapati, Tirha Pura Penyungsungan (alm), Tirtha Kemulan/Merajan (alm), dan Upakara (Banten) Prayascita;','147-148');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (103,1,'Upakaranya (Bantennya) hanya cukup Prayascita sebagai simbol penyucian diri terutama ibu Sang Bayi dan keluarga.','148');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (104,1,'a) Banten Pejati ke Sanggar Surya dan Sanggah Kemulan (Bhatara Hyang Guru)','148');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (105,1,'b) Caru Eka Sata (Ayam Brumbun) dan runtutannya menggunakan Sanggar Cucuk.','148');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (106,1,'c) Prayascita , Durmanggala dan Byakala, serta Segehan.','148');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (107,1,'2) Jika Sawa (Jenasah) tidak ada dirumah diselesaikan diluar rumah (Rumah Duka atau Rumah Sakit) cukup menggunakan upakara (banten) Prayascita.','148');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (108,1,'a) Pras, Ajuman, Daksina, Sodan/Rayunan/ Ajuman, Tipat kelanan (Surya, Sanggar Kemulan, dan Sang Pemuput)','149-150');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (109,1,'b) Banten penjemputan di depan rumah calon suami : Segehan cacahan warna lima, api takep, tetabuhan tuak, arak, berem dan air.','150');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (110,1,'c) Banten tataban Sang Wiwaha : Tumpeng pitu, Biyakala, Durmanggal, Prayascita, Banten pedengen-dengen (pekala-kalaan) di tambah Tebasan Nganten, dan Banten Pejati (Jauman).','150');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (111,1,'d) Banten Sor : Segehan.','150');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (112,1,'a) Upakara (Banten) Pras, Daksina, Sodan/ Rayunan/Ajuman, Tipat kelanan, Suci Sar/Alit (Surya, Sanggar Kemulan, Sang Pemuput)','150');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (113,1,'b) Banten penjemputan di depan rumah calon suami : sama dengan di atas dilengkapi dengan caru petemon.','150');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (114,1,'b) Banten tataban Sang Wiwaha : Tumpeng 21 (Selikur), Banten Byakala Banten Durmanggala, Prayascita, banten pedengen- dengen (pekala-kalaan), Pula gembal, Sekar setaman., ditambah dengan Tebasan Nganten, Jati Semara, Pengenteg Semara, Sesayut Dirgayusa, Bagia setata, Tulus ayu, Pepek tuwuh. Serta Banten Pejati (Jauman).','150');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (115,1,'d) Upakara (Banten) Sor : Segehan agung.','151');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (116,1,'a) Upakara (Banten) Pras, Daksina, Sodan/ Rayunan/Ajuman, Tipat kelanan. (Surya, Sanggar Kemulan, Sang Pemuput)','151');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (117,1,'b) Upakara (Banten) tataban yang hamil: Biyakala, Prayascita, Tumpeng Pitu, Banten Pegedong-gedongan lengkap dengan rujak-rujakan, Sesayut pemahayu tuwuh ditambah Priuk tanah yang di isi air pancuran dengan bunga 11 jenis.','151');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (118,1,'d) Segehan.','151');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (119,1,'2) Upakara/Banten besar. a) Upakara (Banten) Pras, Daksina, Sodan/ Rayunan/Ajuman, Tipat kelanan, Suci Sari/Alit (Surya, Kemulan dan Sang Pemuput)','151');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (120,1,'b) Upakara (Banten) tataban yang hamil: Biyakala, Prayascita, Tumpeng 21 (Selikur) Mapulagembal, Sekar Setaman disertai sarana penglukatan menggunakan lis gede, Sesayut Pemahayu Tuwuh, Sesayut Tulus Dadi ditambah Priuk tanah yang di isi air pancuran dengan bunga 11 jenis.','152');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (121,1,'d) Upakara (Banten) Sor : Segehan agung. Dan dilengkapi dengan Upakara (Banten) Caru di tempat permadian.','152');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (122,1,'a) Canang Sari (Surya, Kemulan, Pertiwi)','152');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (123,1,'b) Upakara(Banten) di Ari-ari Dapetan, Canang Sari dengan kelengkapan Kelapa yang dipecah jadi dua atau dapat juga menggunakan Payuk Pere/Periuk Tanah (Kendi air) yang dibungkus kain putih, didalam Kelapa atau Payuk Pere/Periuk Tanah (Kendi air) dimasukkan Ari-ari, Base lekesan, dilengkapi secarik kertas bertuliskan aksara suci.','152');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (124,1,'c) Upakara (Banten) Sor : Segehan nasi kepel, 4 kepel dijadikan satu tempat, ikannya bawang, jahe dan garam','153');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (125,1,'a) Canang Sari (Surya, Kemulan, Pertiwi)','153');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (126,1,'b) Upakara(Banten) di Ari-ari Dapetan, Penyeneng, Jerimpen Canang Sari dengan kelengkapan Kelapa yang dipecah jadi dua atau dapat juga menggunakan Payuk Pere/Periuk Tanah (Kendi air) yang dibungkus kain putih, didalam Kelapa atau Payuk Pere dimasukkan Ari-ari, Base lekesan, dilengkapi secarik kertas bertuliskan aksara suci.','153');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (127,1,'c) Upakara (Banten) Sor : Segehan nasi kepel, 4 kepel dijadikan satu Tempat, ikannya bawang, jahe dan garam','153');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (128,1,'a) Upakara (Banten) Pebersihan/Pengerisikan dilengkapi dengan bija Kuning beralaskan dua lembar daun dadap, upakara (banten) ini dihaturkan pada pelinggih-pelinggih/ pelangkiran, sumur, dapur, kamar yang ada dirumah.','153-154');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (129,1,'b) Upakara (Banten) Sodan/Rayunan/Ajuman, labahan si Ibu.','154');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (130,1,'c) Upakara (Banten) untuk Kumara : Sodan/ Rayunan/Ajuman, tali pusar si bayi dibungkus kain ditaruh dalam Kumara dengan dilengkapi angat-angat atau rempah-rempah.','154');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (131,1,'d) Upakara (Banten) di Ari-ari : Nasi kepel 4 warna dengan lauk pauk bawang, jahe, dan garam dilengkapi dengan Canang Genten.','154');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (132,1,'a) Upakara (banten) Pras, Daksina, Sodan/ Rayunan/Ajuman, Tipat Kelanan (Surya, Kemulan, Sang Pemuput).','154');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (133,1,'b) Upakara (Banten) Pebersihan Ibu : Byakala, Prayascita, Penglukatan.','154');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (134,1,'c) Upakara (Banten) Pebersihan Bayi di Sumur, Dapur, dan Kemulan : Pras, Sodan/Rayunan/Ajuman. Tumpeng Pras berwarna hitam disumur, Tumpeng Pras warna merah di dapur, dan Tumpeng Pras warna putih di kemulan, Tutug Tuwuh, Purna Jiwa.','154');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (135,1,'c) Upakara (Banten) Tataban si-Bayi: Tumpeng pitu, Pecolongan, Jejangan dan Kumara.','154');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (136,1,'d) Upakara (Banten) Sor : Segehan.','155');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (137,1,'a) Upakara (Banten) Pras, Daksina, Sodan/ Rayunan/Ajuman, Tipat Kelanan (Surya, Kemulan, Sang Pemput).','155');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (138,1,'b) Upakara (Banten) Pebersihan Ibu : Byakala, Durmanggala, Prayascita dan Penglukatan.','155');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (139,1,'c) Upakara (Banten) Pebersihan si Bayi : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, untuk Tumpeng Pras di sumur warna hitam, di dapur warna merah, dan kemulan putih.','155');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (140,1,'d) Upakara (Banten) Tataban si-Bayi : Tumpeng Pitu, Jejangan, Pacolongan, lengkap dengan ayam jantan-betina, Pesuwungan, Kumara. Sayut Tutug Tuwung, Purna Jiwa.','155');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (141,1,'e) Upakara (Banten) Sor : Segehan.','155');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (142,1,'a) Upakara (Banten) Pras, Daksina, Sodan/ Rayunan/Ajuman, Tipat kelanan (Surya, Sanggah Kemulan dan Sang Pemuput)','155');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (143,1,'d) Upakara (Banten) Tataban si Bayi : Tumpeng pitu, Pekakulan, Sambutan, Jejanganan, Banten ngilehan lesung, Banten Kumara, Banten Ari-ari,','155-156');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (144,1,'e) Upakara (Banten) Sor : Segehan.','156');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (145,1,'a) Upakara (Banten) Pras, Daksina, Sodan/ Rayunan/Ajuman, Tipat kelanan, Suci (Surya, Sanggah Kemulan, dan Sang Pemuput)','156');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (146,1,'b) Upakara (Banten) Tataban si Bayi: Tumpeng tujuh belas atau pitulas, Banten Sambutan, Jejanganan, Pekakulan, Banten ngilehan lesung, Pulagembal, Sekar setaman, Sesayut Pageh Tuwuh, Purna Jiwa, Suka langgeng setata, Tulus Ayu, Imbuh Tuwuh.','156');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (147,1,'c) Banten Sor : Segehan Agung.','156');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (148,1,'a) Upakara (Banten) Pras, Daksina, Sodan/ Rayunan/Ajmuman, Tipat kelanan (Surya, Sanggar Kemulan dan Sang Pemuput)','156');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (149,1,'b) Upakara (Banten) Tataban si Bayi : Tumpeng pitu, Banten Jejanganan, Banten Sambutan, Banten turun tanah, Banten Gunting rambut, ditambah dengan 5 buah sesayut otonan : Sesayut Pageh tuwuh, Purna jiwa, Suka langgeng setata, imbuh tuwuh dan Tulus ayu.','156-157');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (150,1,'c) Banten Sor : Segehan.','157');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (151,1,'a) Upakara (Banten) Pras, Daksina, Sodan, Rayunan,Ajuman, Tipat kelanan, Suci 1 soroh (Surya, Sanggah Kemulan dan Sang Pemuput)','157');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (152,1,'b) Banten Tataban si Bayi : Tumpeng 21 (Selikur), Banten Jejanganan, Banten Sambutan, Banten turun tanah, Banten Gunting rambut, Jerimpen, Pulagembal, Sekar setaman, Sayut Tutug Tuwuh, Purna Jiwa, Tulus Ayu, Suka Langgeng Setata.','157');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (153,1,'c) Banten Sor : Segehan Agung.','157');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (154,1,'a) Upakara (Banten) Pras, Daksina, Sodan/ Rayunan/Ajuman, Tipat Kelanan (Surya, Kemulan dan Sang Pemuput)','157-158');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (155,1,'b) Upakara (Banten) Pebersihan : Byakala, Prayascita.','157');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (156,1,'c) Upakara (Banten) Tataban : Tumpeng pitu, dan Sesayut Ngerajasina (untuk yang laki- laki) dan untuk wanita ditambah upakara (banten) Pededarian dan Sesayut Sabuh Rah.','157-158');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (157,1,'d) Upakara (Banten) Sor : Segehan.','158');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (158,1,'a) Upakara (Banten) Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan (Surya, Kemulan, Sanghyang Semara Ratih, Sangging)','158');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (159,1,'b) Upakara (Banten) Pebersihan : Byakala, Prayascita, Penglukatan.','158');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (160,1,'c) Upakara (Banten) Tataban : Tumpeng pitu dengan perlengkapan Kasur, bantal, tikar yang bergambar Semara Ratih, Bale Gading, Kelapa gading, Singgang gigi (pedangal), Pengilap, Sarana pengurip-urip (biyang kunyit yang dikupas kulitnya, Bokor berisi (kikir, cermin, dan pahat), Sebuah tempat sirih lengkap dengan sirih lekesan, tembakau, pinang dan kapur (gambir), Kain untuk menutupi badan (rurub), Upakara (Banten) Tetingkeb.','158');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (161,1,'1) Banten Pesaksi : Pras, Daksina dan Suci asoroh.','166');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (162,1,'2) Banten persiapan pembersihan Byakala, Prayascita dan Penglukatan.','166');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (163,1,'3) Banten Pewintenan Pras, Daksina dan Suci asoroh, Tumpeng Pitu, Banten 4) Saraswati dan Sesayut Sudamala.','166');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (164,1,'6) Banten untuk Sang Pemuput (Pandita) : Pras, Daksina dan Suci asoroh.','166');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (165,1,'2) Banten persiapan pembersihan Byakala, Prayascita, dan Penglukatan.','166');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (166,1,'3) Banten Pewintenan Pras Daksina dan Suci asoroh, Tumpeng Guru maplekir, Banten Saraswati, Pulagembal, memakai itik/bebek putih sarana pesosolan, Kewangen berisi Uang kepeng 11 dibungkus Kain putih dan Banten Pedamel, serta Sesayut Sudamala.','166');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (167,1,'a) Upakara (Banten) Pras, Daksina, Sodan/ Rayunan/Ajuman, Tipat kelanan (Surya, Pertiwi, Sang Pemuput).','168');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (168,1,'b) Upakara (Banten) Caru : Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat kelanan, Tupeng Pitu, Bayuan Alit, Olahan Caru lengkap dengan nasi caru, Nasi wong-wongan, Byakala, Segehan, Upakara (banten) Gelarsanga.','168');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (169,1,'c) Upakara (Banten) Pebersihan : Durmanggala, Prayascita dan Penglungkatan menggunakan Lis gede.','168');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (170,1,'a) Pras, Ajuman, Daksina, Tipat kelanan, Suci sari/Alit (Surya, Pertiwi, Sang Pemuput)','169');
